"""Summarize the 8- and 32-iteration XPBD traces generated by bench.py."""

import csv
from pathlib import Path

import numpy as np

here = Path(__file__).resolve().parent
rows = []
for iterations in (8, 32):
    with (here / f"xpbd{iterations}.csv").open() as stream:
        traces = {}
        for r in csv.DictReader(stream):
            traces.setdefault(r["catheter"], []).append(
                [
                    float(r[k])
                    for k in (
                        "displacement_mm",
                        "nose_N",
                        "supports_N",
                        "guide_gap_mm",
                        "guide_offset_mm",
                    )
                ]
            )
    assert len(traces) == 4
    for name, samples in traces.items():
        data = np.asarray(samples)
        assert data.shape == (938, 5) and np.isfinite(data).all()
        assert (
            np.all(np.diff(data[:, 0]) > 0)
            and data[-1, 0] == 5
            and max(data[:, 4]) < 60 / 27 / 2
        )
        i = np.flatnonzero(data[:, 0] == 4).item()
        rows.append(
            dict(
                catheter=name,
                iterations=iterations,
                nose_at_4mm_N=data[i, 1],
                summed_supports_at_4mm_N=data[i, 2],
                maximum_guide_gap_mm=max(data[:, 3]),
                maximum_guide_offset_mm=max(data[:, 4]),
            )
        )
with (here / "summary.csv").open("w") as stream:
    writer = csv.DictWriter(stream, fieldnames=rows[0])
    writer.writeheader()
    writer.writerows(rows)
